<?php
declare(strict_types=1);

namespace Site;

/** Site icons and web app manifest (C1), generated by src/lib/favicon.php. */
final class Icons
{
    /** GET /icons/{sig}/{file}: immutable when the signature is current, otherwise the current file briefly cached. */
    public static function file(array $p): void
    {
        $file = (string) $p['file'];
        if (!isset(FAVICON_FILES[$file])) {
            abort(404);
        }
        $sig = favicon_ensure();
        if ($sig === null) {
            abort(404);
        }
        self::send(favicon_dir($sig) . '/' . $file, FAVICON_FILES[$file][0], $p['sig'] === $sig ? 'public, max-age=31536000, immutable' : 'public, max-age=3600');
    }

    /** GET /favicon.ico and /apple-touch-icon.png: browsers ask for these at the root. */
    public static function root(array $p): void
    {
        $file = request_path() === '/apple-touch-icon.png' ? 'apple-touch-icon.png' : 'favicon.ico';
        $sig = favicon_ensure();
        if ($sig === null) {
            abort(404);
        }
        self::send(favicon_dir($sig) . '/' . $file, FAVICON_FILES[$file][0], 'public, max-age=86400');
    }

    public static function manifest(array $p): void
    {
        header('Content-Type: application/manifest+json; charset=utf-8');
        header('Cache-Control: public, max-age=' . (query_param('v') === favicon_manifest_version() ? '31536000, immutable' : '3600'));
        header('X-Content-Type-Options: nosniff');
        echo json_encode(favicon_manifest(), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT | JSON_THROW_ON_ERROR);
    }

    private static function send(string $path, string $mime, string $cache): never
    {
        if (!is_file($path)) {
            abort(404);
        }
        $etag = '"' . substr(sha1_file($path) ?: '', 0, 16) . '"';
        header('Content-Type: ' . $mime);
        header('Cache-Control: ' . $cache);
        header('ETag: ' . $etag);
        header('X-Content-Type-Options: nosniff');
        if (($_SERVER['HTTP_IF_NONE_MATCH'] ?? '') === $etag) {
            http_response_code(304);
            exit;
        }
        header('Content-Length: ' . (string) filesize($path));
        if (request_method() !== 'HEAD') {
            readfile($path);
        }
        exit;
    }
}
